(()=>{const h=window.__wolfTest,panel=document.createElement('aside');panel.style='position:fixed;top:4px;left:4px;z-index:400;background:#fff;color:#123;max-width:340px;max-height:160px;overflow:auto;padding:6px';panel.innerHTML='<b>救援微场景 · 预置局面，非完整关卡</b><div>'+['seen','unseen','late','door','contact','dual'].flatMap(k=>['easy','hard'].map(d=>'<button data-case="'+k+'" data-difficulty="'+d+'" data-real="false">'+k+' '+d+' 假羊</button>')).join('')+['easy','hard'].map(d=>'<button data-case="seen" data-difficulty="'+d+'" data-real="true">seen '+d+' 真羊</button>').join('')+'</div><button id="readRescue">读取行动结果</button><pre id="rescueReceipt" style="white-space:pre-wrap"></pre>';document.body.appendChild(panel);panel.onclick=e=>{const b=e.target;if(!b.dataset.case)return;h.dismissAllGuides();h.setDifficulty(b.dataset.difficulty);h.load('d23');h.clean();h.start();h.clean();h.patch(rescueScene(b.dataset.case,b.dataset.real==='true'));h.render();document.getElementById('rescueReceipt').textContent='已载入 '+b.textContent;};document.getElementById('readRescue').onclick=()=>{const s=h.state();document.getElementById('rescueReceipt').textContent=JSON.stringify({round:s.round,mode:s.mode,guards:[s.guard,s.otherGuard],sheep:s.sheep.map(({id,x,y,snared})=>({id,x,y,snared})),rescueCount:s.rescueCount,events:s.guardEvents,trap:s.trapFx})};})();
